    // ── THE SUPER AUTO BUILDER ───────────────────────────────────────────────
    // How many ticks a super auto builder waits on one cell - its next cell blocked - before
    // it gives up and dies (into ent_super_auto_builder_death). Its GOOD channel is the clock:
    // +1 a tick, fired the tick it REACHES this (the row's good max is this - 1), and started
    // again from 0 every time the builder steps, so a walk that keeps moving never gets near
    // it however long the blueprint is. Ticks, so 1000 is about 67 seconds at 15 a second.
    // NU_SUPER_AUTO_BUILDER_ENT in entity_templater.js.
    SUPER_AUTO_BUILDER_PATIENCE: 1000,

    // ── TWO SPAWNERS ON A CLOCK (MORE RELIC ACTIONS, bottom of all_ents.js) ─────
    // Each is one row: its GOOD channel spawns one of something every PROD + 1 ticks (+1 a
    // tick, fires on > max, and a spawn takes max + 1 back off it), its TRANS1 is its life.
    // An unhindered spawn LANDS on ticks (PROD + 1) * k + 1, and the next one is AIMED on
    // tick (PROD + 1) * (k + 1) - so the life (a max: it ends on tick TIME + 1, and that
    // self transform beats a spawn being aimed on the same tick) gives exactly COUNT of
    // them when  COUNT * (PROD + 1) <= TIME <= (COUNT + 1) * (PROD + 1) - 1.  The top of
    // that range leaves the most room for a late one; the check under CL holds the build to
    // it. A spawn that cannot land (its cell taken) banks on the good channel and comes out
    // as soon as there is room - but only while the spawner lives, so a long hold-up costs it
    // the last ones.
    //
    // THE DIRECTIONAL DIGGER - a miner out to its right (XFORM.SPAWN_E) every 12 ticks,
    // DIRECTIONAL_DIGGER_MINERS of them. It is a MINER itself, so dropped against rock it chews
    // its way out first (the walls all round it, not only the one to its right). The miners
    // queue behind whichever is digging at the front, so the digging power is what keeps them
    // coming on time; rock hard enough to hold the queue up past the digger's life costs it the
    // last ones.
    PROD_DIRECTIONAL_DIGGER_MINER:  11,     // good max - a miner every 12 ticks
    DIRECTIONAL_DIGGER_MINERS:      14,     // how many (not in the row - the life below is what holds it to this)
    DIRECTIONAL_DIGGER_TIME:        171,     // trans1 max - its life: ends on tick 172, after the 14th lands (tick 169); 179 would give a late one more room
    DIRECTIONAL_DIGGER_PWR:         60,     // bad power - what it takes off each wall next to it a tick (CL.STD_WALL_HEALTH 420 in 8)
    // ...and the miners: walk right for good (DESIRE_PERM), take DIRECTIONAL_MINER_PWR off every
    // wall next to them a tick, and crumble when their life is up. Not warriors - a tunnelling tool.
    DIRECTIONAL_MINER_TIME:         99,     // trans1 max - a miner lives 100 ticks
    DIRECTIONAL_MINER_PWR:          75,     // bad power - per wall next to it, per tick
    //
    // THE MASKER BURST - a masker runner out onto a random free neighbour every 2 ticks, aimed
    // away from it (XFORM.SPAWN_INHERIT_VEL), sixteen of them. Each runs straight on
    // (DESIRE_PERM), leaving an ent_scentblocker on every cell it steps off.
    PROD_MASKER_BURST_RUNNER:       1,      // good max - a runner every 2 ticks
    MASKER_BURST_RUNNERS:           16,     // how many (not in the row - the life below is what holds it to this)
    MASKER_BURST_CALLER_TIME:       33,     // trans1 max - its life: ends on tick 34, when a seventeenth would be aimed
    MASKER_RUNNER_TIME:             99,     // trans1 max - a runner lives 100 ticks

    // ── THE WISDOM MARKER ('r') ──────────────────────────────────────────────
    // How many sim ticks a marker stands after 'r' places it (or refreshes it -
    // pressing 'r' again anywhere restarts the count). Every one of those ticks
