// ── WHICH LEVEL THE WORLD BEING BUILT IS ────────────────────────────────────
// The one answer, for everything in Ex9_Stimmings2() that needs it: the background (at the
// top of the world, before the database packs it), the LEVEL SEED and levelWorldRecipe()
// (further down). It reads only what index2.html sets BEFORE a world is entered, in the
// order that has always decided it:
//   a REPLAY names its own world      - PENDING_REPLAY.level   (startReplay)
//   a PORTAL names the next one       - PENDING_NEXT_LEVEL.level (beginNextLevel)
//   a LOAD carries its level          - INCOMING_META.currentLevel, when it is a level
//   anything else - first boot, the map dropdown - is level 1.
// The first two are handed back exactly as given (not floored): the LEVEL SEED hashes the
// number as text, and a different spelling would be a different world.
function levelOfTheWorldBeingBuilt(){
    if( typeof PENDING_REPLAY !== 'undefined' && PENDING_REPLAY ){
        return PENDING_REPLAY.level;
    }
    if( typeof PENDING_NEXT_LEVEL !== 'undefined' && PENDING_NEXT_LEVEL ){
        return PENDING_NEXT_LEVEL.level;
    }
    if( WANT_TO_LOAD_NEW && INCOMING_META && typeof INCOMING_META.currentLevel === 'number'
        && isFinite( INCOMING_META.currentLevel ) && INCOMING_META.currentLevel >= 1 ){
        return Math.floor( INCOMING_META.currentLevel );
    }
    return 1;
}

// ── THE BACKGROUND, BY LEVEL ────────────────────────────────────────────────
// Level N draws background (N - 1) mod howMany - BACKGROUND_FILES in util/scruncher.js, in
// order, round and round: level 1 the first, level howMany the last, then the first again.
// Anything that is not a level (a hand-edited save) draws the first. Render only: the
// compute shader never reads the background, so this cannot touch the sim, a replay or a save.
function backgroundForLevel( level, howMany ){
    if( !( typeof level === 'number' && isFinite( level ) && level >= 1 ) || !( howMany >= 1 ) ){ return 0; }
    return ( Math.floor( level ) - 1 ) % howMany;
}





