var ALL_SFX_KEYS=["sfx_convert","sfx_dslr_cam","sfx_achievement_techno","sfx_achievement_triumph","sfx_new_crumblethump","sfx_new_truman_mcrumpp","sfx_perfect_ting","sfx_faith_charge_up","sfx_bsketball_dribble","sfx_chompter_spawn","sfx_pang","sfx_vill","sfx_stim_death","sfx_metalclaing","sfx_another_pat","sfx_homemaker","sfx_homeconv","sfx_supp_boost","sfx_war_cmd_spanwed","sfx_horsesnort","sfx_dot","sfx_r_pang","sfx_bombom","sfx_banner_notif","sfx_good_sparkle","sfx_knighter","sfx_metal_ting3","sfx_whoop","sfx_man_death_sound","sfx_building_goinup","sfx_metal_ting1","sfx_pressurerelease","sfx_metal_ting2","sfx_frog_or_failure","sfx_bass_boom","sfx_leader_collapse","sfx_quirky_pain","sfx_breiup","sfx_vgai_miniboss_groan","sfx_quiet_complain","sfx_evil_demon_screech","sfx_key_drop","sfx_audible_ow","sfx_more_pain","sfx_baloop","sfx_ghost_death","sfx_evil_stopped","sfx_mine1_exp","sfx_icespell","sfx_barracks_disharge","sfx_another_rev_reumble","sfx_faithmage_acivhe","sfx_phit_ting","sfx_ominous","sfx_florpenator","sfx_charge_show","sfx_alien_radar","sfx_one_subtle_bang","sfx_alien_sentryoutlook","sfx_alien_bowwmm"];

// The scruncher's sprite array, value for value: compile.js makes this
// var entireImgBuffer = EZ_PIXELS( 'entireImgBuffer' ).
var entireImgBuffer = EZ_PIXELS( 'entireImgBuffer' );

// The level, decided up here because the background is: compile.js makes the placeholder
// below  var entireBgBuffer = EZ_PIXELS( 'entireBgBuffer', thisWorldBackground );  - THIS
// world's background only (THE BACKGROUND, BY LEVEL, above). stimmings_db.js puts it at
// SCHEMA_INDEX.bg_start, where the fragment shader has always read the background, so
// EZ_STORAGE stays one background long however many there are and no offset after it moves.
var thisWorldLevel      = levelOfTheWorldBeingBuilt();
var thisWorldBackground = backgroundForLevel( thisWorldLevel, EZ_PIXELS.count( 'entireBgBuffer' ) );
console.log( 'level', thisWorldLevel, '- background', thisWorldBackground, 'of', EZ_PIXELS.count( 'entireBgBuffer' ) );
var entireBgBuffer = EZ_PIXELS( 'entireBgBuffer', thisWorldBackground );

// The blueprints go in ABOVE the database: stimmings_db.js packs every blueprint's build
