function NU_ENT( variableString, entireDef){
    STAD[''+variableString] = FullEntEntries.length;
    FullEntEntries.push(
        entireDef
    );
} 
  
 
function NU_RES_ENT( entNameVariable, miobj, amtOfRes, frameTime, animationMode ){
    NU_ENT( ""+entNameVariable, [
        ""+miobj.n,                                              //Names
        ""+miobj.d,                                              //Desc
        ["sfx_phit_ting", "", "", ""],                                       // Sounds
        ""+miobj.animpckge,                                                 // Animation package
        PHYS.PHYSICS_RES,                                     // Physics flags of the entity
        EZWG.createPackedU32_16( EZWG.createPackedU16_8(STAD[""+miobj.animpckge][2], frameTime), STAD[""+miobj.animpckge][1] ),  // animSize, animFreq, animStart (16 bytes)
        EZWG.createPackedU32( 0, ( animationMode.sync?(0^CL.DESYNC_ANIM_BIT):(0) ) + (animationMode.wind?4:0), CL.FREQ_VFAST, DESIR.DESIRE_NOTHING ),// Flippaleprofile, [0x4bit for wind 0x2 bit (0=desynced, 1=synced animations) steppable=0(1=yes)], MoveFreq, Desire
        
        EZWG.createPackedU32_16( animationMode.waterfloat?(STAD.dmg_wall_water_proof):0, STAD.scnt_res_block ),                    //  Damage Profile ID (max of 65535),Scent Profile ID (max of 65535),
    
        PHYS.PHYSICS_MINER | PHYS.PHYSICS_HOMEBASE,                    // Goodness from profile
        PHYS.PHYSICS_RES_WORKER | PHYS.PHYSICS_MINER | PHYS.PHYSICS_HOMEBASE,  // Badness from profile, 
        0,                    // Trans1 from profile 
        0,                    // Trans2 from profile, 
        
        EZWG.createPackedU32_16( amtOfRes, CL.STD_VFX_TRGER ),            // Badness max, Goodness max
        EZWG.createPackedU32_16( 65535, 65535 ),            // Trans 2 max, Trans 1 max
        
        EZWG.createPackedU32_16( CL.STD_NRM_PWR, CL.STD_NRM_PWR ),                    // Badness power, Goodness power (badness amt hurts YOU when spawn of result t ype 4 occured)
        EZWG.createPackedU32_16( 1, 1 ),                    // Trans 2 power, Trans 1 power
    
        EZWG.createPackedU32_16( 0, 0 ),                    // Badness ambient, Goodness ambient
        EZWG.createPackedU32_16( 0, 0 ),                    // Trans 2 ambient, Trans 1 ambient
    
        EZWG.createPackedU32_16( animationMode.replacerEnt?animationMode.replacerEnt:0,         //<-----//Badness result
            animationMode.visualEntOveride?animationMode.visualEntOveride:STAD.ent_dust_chips),//STAD.ent_smw_coin ),                    //   Goodness result
        EZWG.createPackedU32_16( 0, 0 ),                    // Trans 2 result, Trans 1 result
    
        EZWG.createPackedU32( 0, 0, 0, 1 ),                 // TYPE OF TRANSOFRM, trans 2, trans 1, bad, good
                                                            // 0 = self transofmr, 1 = random direction spawn, 2=random direction spawn NO TEAM,     3 = inherit velocity..., 4=damage yurself on spawn from OWN power
    
        EZWG.createPackedU32( 0, 0, 0, 0 ),              //  -ONE Shot or not (1 yes, 0 is cummulatibve)
        EZWG.createPackedU32_16( Math.floor(Math.ceil(amtOfRes/CL.PROD_STIM_HOME)*2), 0 ),            // BP build cost, drop value every move
    
    ]);
}



// The CASING a tier relic is broken out of. NU_RES_ENT's row exactly - workers smell
// it as a resource and chip at it like one - except for two fields:
//
//   PHYSICS   + ALLEGIANCED + SUGGESTIVE. The first teamed, allegianced thing to touch
//             it claims it (the neutral team conversion in the neighbour loop of
//             stimmings_compute.wgsl), and the bad channel's self transform keeps the
//             team, so the relic comes out ALREADY carrying the team that released it.
//             That team is what decides whose stash it goes in (catalogRelicType in
//             Ex9). Broken by something with no team - a worm, a bomb's blast - before
//             any team touched it, the relic comes out team 0 and is LOST.
//   BAD MAX   CL.RELIC_CASING_RES instead of a resource amount, so it opens on contact
//             rather than after a whole harvest.
//
// The build cost is still worked out from CL.RES_STD_AMT exactly as it was when these
// rows were NU_RES_ENTs - it prices BUILDING a casing, not opening one.
function NU_RELIC_CASING_ENT( entNameVariable, relicEnt, miobj, frameTime, animationMode ){
    NU_ENT( ""+entNameVariable, [
        ""+miobj.n,                                              //Names
        ""+miobj.d,                                              //Desc
        ["sfx_phit_ting", "", "", ""],                                       // Sounds
        ""+miobj.animpckge,                                                 // Animation package
        PHYS.PHYSICS_RES | PHYS.PHYSICS_ALLEGIANCED | PHYS.PHYSICS_SUGGESTIVE,                                     // Physics flags of the entity
        EZWG.createPackedU32_16( EZWG.createPackedU16_8(STAD[""+miobj.animpckge][2], frameTime), STAD[""+miobj.animpckge][1] ),  // animSize, animFreq, animStart (16 bytes)
        EZWG.createPackedU32( 0, ( animationMode.sync?(0^CL.DESYNC_ANIM_BIT):(0) ) + (animationMode.wind?4:0), CL.FREQ_VFAST, DESIR.DESIRE_NOTHING ),// Flippaleprofile, [0x4bit for wind 0x2 bit (0=desynced, 1=synced animations) steppable=0(1=yes)], MoveFreq, Desire

        EZWG.createPackedU32_16( animationMode.waterfloat?(STAD.dmg_wall_water_proof):0, STAD.scnt_res_block ),                    //  Damage Profile ID (max of 65535),Scent Profile ID (max of 65535),

        PHYS.PHYSICS_MINER | PHYS.PHYSICS_HOMEBASE,                    // Goodness from profile
        PHYS.PHYSICS_RES_WORKER | PHYS.PHYSICS_MINER | PHYS.PHYSICS_HOMEBASE,  // Badness from profile,
        0,                    // Trans1 from profile
        0,                    // Trans2 from profile,

        EZWG.createPackedU32_16( CL.RELIC_CASING_RES, CL.STD_VFX_TRGER ),            // Badness max, Goodness max
        EZWG.createPackedU32_16( 65535, 65535 ),            // Trans 2 max, Trans 1 max

        EZWG.createPackedU32_16( 1, 1 ),                    // Badness power, Goodness power (badness amt hurts YOU when spawn of result t ype 4 occured)
        EZWG.createPackedU32_16( 1, 1 ),                    // Trans 2 power, Trans 1 power

        EZWG.createPackedU32_16( 0, 0 ),                    // Badness ambient, Goodness ambient
        EZWG.createPackedU32_16( 0, 0 ),                    // Trans 2 ambient, Trans 1 ambient

        EZWG.createPackedU32_16( relicEnt,         //<-----//Badness result
            animationMode.visualEntOveride?animationMode.visualEntOveride:STAD.ent_dust_chips),//STAD.ent_smw_coin ),                    //   Goodness result
        EZWG.createPackedU32_16( 0, 0 ),                    // Trans 2 result, Trans 1 result

        EZWG.createPackedU32( 0, 0, 0, 1 ),                 // TYPE OF TRANSOFRM, trans 2, trans 1, bad, good
                                                            // 0 = self transofmr, 1 = random direction spawn, 2=random direction spawn NO TEAM,     3 = inherit velocity..., 4=damage yurself on spawn from OWN power

        EZWG.createPackedU32( 0, 0, 0, 0 ),              //  -ONE Shot or not (1 yes, 0 is cummulatibve)
        EZWG.createPackedU32_16( CL.BP_UNN_BUILD_COST, 0 ),            // BP build cost, drop value every move

    ]);
}

function NU_RELIC_ENT( entNameVariable, miobj, frameTime, animationMode ){
    NU_ENT( ""+entNameVariable, [
        ""+miobj.n,                                              //Names
        ""+miobj.d,                                              //Desc
        ["sfx_phit_ting", "", "", ""],                                       // Sounds
        ""+miobj.animpckge,                                                 // Animation package
        // JS binds | TIGHTER than ?: , so the old one-liner here parsed as
        // (PHYSICS_RELIC | dropExtraTimeOverride) ? (ALLEGIANCED|SUGGESTIVE) : 0 - and since
        // PHYSICS_RELIC is 1<<30 that condition is ALWAYS truthy, so every relic came out as
        // a bare 16388 and the RELIC BIT WAS NEVER SET ON ANY OF THEM. That is what makes the
        // PHYSICS_RELIC sweep in Ex9 (tallyRelicEntity) find nothing: it gates on this field.
        //
        // ALLEGIANCED, and deliberately NOT SUGGESTIVE. A relic's team is the team that
        // released it (NU_RELIC_CASING_ENT) and has to stay that way until the census reads
        // it, because that team is whose stash it goes in. SUGGESTIVE would let any teamed
        // unit standing next to a team 0 relic adopt it before the sweep came round. A relic
        // DROPPED off the tier 5 pool is still yours: the RELIC DROP block in
        // stimmings_compute.wgsl hands the session team to anything ALLEGIANCED.
        PHYS.PHYSICS_RELIC | PHYS.PHYSICS_ALLEGIANCED,                                     // Physics flags of the entity
        EZWG.createPackedU32_16( EZWG.createPackedU16_8(STAD[""+miobj.animpckge][2], frameTime), STAD[""+miobj.animpckge][1] ),  // animSize, animFreq, animStart (16 bytes)
        EZWG.createPackedU32( 0, ( animationMode.sync?(0^CL.DESYNC_ANIM_BIT):(0) ) + (animationMode.wind?4:0), CL.FREQ_VFAST, DESIR.DESIRE_NOTHING ),// Flippaleprofile, [0x4bit for wind 0x2 bit (0=desynced, 1=synced animations) steppable=0(1=yes)], MoveFreq, Desire
        
        EZWG.createPackedU32_16( animationMode.waterfloat?(STAD.dmg_relic_perfect):0, STAD.scnt_std_wall ),                    //  Damage Profile ID (max of 65535),Scent Profile ID (max of 65535),
    
        0,                    // Goodness from profile
        0,  					// Badness from profile, 
        0,                    // Trans1 from profile 
        0,                    // Trans2 from profile, 
        
        EZWG.createPackedU32_16( 65535, 65535 ),            // Badness max, Goodness max
        EZWG.createPackedU32_16( animationMode.dropExtraTimeOverride?(CL.RELIC_LIFE_TIME*10):CL.RELIC_LIFE_TIME, 65535 ),            // Trans 2 max, Trans 1 max
        
        EZWG.createPackedU32_16( 1, 1 ),                    // Badness power, Goodness power (badness amt hurts YOU when spawn of result t ype 4 occured)
        EZWG.createPackedU32_16( 1, 1 ),                    // Trans 2 power, Trans 1 power
    
        EZWG.createPackedU32_16( 0, 0 ),                    // Badness ambient, Goodness ambient
        EZWG.createPackedU32_16( 1, 0 ),                    // Trans 2 ambient, Trans 1 ambient
    
        EZWG.createPackedU32_16( 0,         //<-----//Badness result
            0),//STAD.ent_smw_coin ),                    //   Goodness result
        EZWG.createPackedU32_16( STAD.ent_book_evap, 0 ),                    // Trans 2 result, Trans 1 result
    
        EZWG.createPackedU32( 0, 0, 0, 0 ),                 // TYPE OF TRANSOFRM, trans 2, trans 1, bad, good
                                                            // 0 = self transofmr, 1 = random direction spawn, 2=random direction spawn NO TEAM,     3 = inherit velocity..., 4=damage yurself on spawn from OWN power
    
        EZWG.createPackedU32( 0, 0, 0, 0 ),              //  -ONE Shot or not (1 yes, 0 is cummulatibve)
        EZWG.createPackedU32_16( CL.BP_UNN_BUILD_COST, 0 ),            // BP build cost, drop value every move
    
    ]);
}

