//  = = = = =   THE SUPER AUTO BUILDER'S PROGRAMS - WHICH BLUEPRINT A RELIC HANDS ITS BUILDER   = = = = =
//  A SUPER AUTO BUILDER (ent_super_auto_builder) carries what it is building in its own
//  channels: Trans1 = WHICH blueprint (its slot - ALLBPS index + 1, 0 = nothing to build) and
//  Trans2 = HOW FAR along that blueprint's walk it is (the step it is standing on). Something
//  has to put those two numbers there, and that is the relic it hatches out of.
//
//  A super auto builder relic is an ordinary action relic (NU_RELIC_ACTION_ENT) whose BAD
//  result is the builder. Registering it here as well is what makes its activation - the
//  CL.RELIC_ACTIVATION_TIME fuse that turns every action relic into its reward, however the
//  relic got onto the map - hand the builder this blueprint and this starting step. The
//  shader reads it out of a per-entity table in the storage buffer (SCHEMA_INDEX.sab_prog_start,
//  packed by src/stimmings_db.js), so a new relic for another blueprint is one more line in
//  util/all_ents.js and nothing in the shader.
//
//      SUPER_AUTO_BUILDER_PROGRAM( "ent_relic_...", "bp_...", startStep )
//
//  startStep is optional (0 = the first cell of the walk, which is the cell the relic is on).
//  The blueprint is named the way mapgen names it: bp_ + the third part of its file name. The
//  scruncher stops the build if it does not exist - see checkAllBlueprints in util/scruncher.js.
//  Register the relic's row FIRST: this looks it up by its STAD key.
var SAB_PROGRAMS = [];
function SUPER_AUTO_BUILDER_PROGRAM( relicEntName, bpName, startStep ){
    var id = STAD[''+relicEntName];
    if( typeof id !== 'number' || id < 1 || !FullEntEntries[id] ){
        throw new Error('SUPER_AUTO_BUILDER_PROGRAM: "' + relicEntName + '" is not a registered entity - put this line after its NU_ entry');
    }
    SAB_PROGRAMS.push({
        ent:  ''+relicEntName,
        id:   id,
        bp:   ''+bpName,
        step: (startStep|0)
    });
}

//  = = = = =   A SUPER AUTO BUILDER   = = = = =
//  Every builder is the same row apart from what it looks like - the blueprint it builds is
//  not in the row at all (Trans1 / Trans2, put there by its relic). So a builder is one line:
//
//      NU_SUPER_AUTO_BUILDER_ENT( "ent_...", {animpckge: "...", n: "...", d: "..."} )
//
//  then its relic and the relic's program, which stay two separate lines on purpose: the
//  dev server expands a template row into a plain NU_ENT when its numbers are edited, and a
//  program registered from inside a template would be lost in that expansion, silently.
//
//      NU_RELIC_ACTION_ENT( "ent_relic_...", STAD.ent_..., {animpckge: "rellic_flash_point", n:"...", d:"..."}, CL.ANIMATION_0FAST, {sync: false, wind: false} );
//      SUPER_AUTO_BUILDER_PROGRAM( "ent_relic_...", "bp_..." );
//
//  frameTime is optional, CL.ANIMATION_SFAST if left out.
//
//  What the row says, and why (the rules that move it are THE SUPER AUTO BUILDER in
//  src/stimmings_compute.wgsl):
//
//    BAD      the warrior's weakness (PHYSPROFS.STD_WARRIOR_badness) - what kills a normal
//             warrior kills a builder - and a standard stim's health (CL.STD_HEALTH). Enemy
//             warriors next to it hurt it as well, as they hurt anything allegianced.
//    GOOD     a waiting clock: +1 a tick, and the tick it reaches
//             CL.SUPER_AUTO_BUILDER_PATIENCE the builder gives up and dies. The shader starts
//             it again from 0 every time the builder steps (ARRIVING ON A CELL), so it only
//             ever counts time spent stuck on one cell - a long blueprint walked without a
//             hitch never comes near it.
//    both     die into ent_super_auto_builder_death, its crumbling animation. (Defined at the
//             end of util/all_ents.js: entity ids only ever append, and the builders came
//             first. Like the hundreds of rows that die into ent_poof_visual, the reference
//             resolves because the bundle runs this file with STAD already holding the ids
//             util/scruncher.js wrote to animation_lookups.js.)
//    TRANS1   which blueprint (its slot)   } the program. ⚠ NOTHING may add to them: no
//    TRANS2   which step of its walk       } from-masks, no ambients, maxes 65535 so neither
//                                            can ever fire - and BAD FROM MUST NEVER EQUAL
//                                            TRANS1 FROM: the neighbour loop also feeds an
//                                            enemy warrior's Trans1 power into any allegianced
//                                            entity whose badFrom == t1From (the team-v-team
//                                            trick next to WARBOOLEAN), which would walk it
//                                            onto another blueprint.
//    SOUNDS   [ gave up waiting, killed, finished the blueprint, - ]. The third is played by
//             THE LAST STEP, through Trans1's slot - a builder's own Trans1 never fires.
function NU_SUPER_AUTO_BUILDER_ENT( entNameVariable, miobj, frameTime ){
    frameTime = ( frameTime === undefined ) ? CL.ANIMATION_SFAST : frameTime;
    NU_ENT( ""+entNameVariable, [
        ""+miobj.n,                                              //Names
        ""+miobj.d,                                              //Desc
        ["sfx_stim_death", "sfx_stim_death", "sfx_good_sparkle", ""],   // Sounds: gave up waiting, killed, finished the blueprint
        ""+miobj.animpckge,                                      // Animation package
        PHYS.PHYSICS_ALLEGIANCED | PHYS.PHYSICS_SUGGESTIVE,      // Physics flags of the entity
        EZWG.createPackedU32_16( EZWG.createPackedU16_8(STAD[""+miobj.animpckge][2], frameTime), STAD[""+miobj.animpckge][1] ),  // animSize, animFreq, animStart (16 bytes)
        EZWG.createPackedU32( 0, 0, CL.FREQ_0FAST, DESIR.DESIRE_SUPER_AUTO_BUILD ),// Flippaleprofile (none - the sprite faces you), [step/anim bits], MoveFreq (as fast as there is), Desire

        EZWG.createPackedU32_16( 0, STAD.scnt_stimming ),        //  Damage Profile ID (max of 65535),Scent Profile ID (max of 65535),

        0,                                  // Goodness from profile    nothing - the good channel is the waiting clock
        PHYSPROFS.STD_WARRIOR_badness,      // Badness from profile     what kills a warrior  ⚠ never the same as Trans1 from
        0,                                  // Trans1 from profile      NOTHING - Trans1 is the blueprint
        0,                                  // Trans2 from profile      NOTHING - Trans2 is the step

        EZWG.createPackedU32_16( CL.STD_HEALTH, CL.SUPER_AUTO_BUILDER_PATIENCE - 1 ),   // Badness max, Goodness max (fires the tick it REACHES the patience)
        EZWG.createPackedU32_16( 65535, 65535 ),            // Trans 2 max, Trans 1 max - neither may ever fire

        EZWG.createPackedU32_16( 1, 1 ),                    // Badness power, Goodness power (badness amt hurts YOU when spawn of result t ype 4 occured)
        EZWG.createPackedU32_16( 1, 1 ),                    // Trans 2 power, Trans 1 power

        EZWG.createPackedU32_16( 0, 1 ),                    // Badness ambient, Goodness ambient - the waiting clock ticks
        EZWG.createPackedU32_16( 0, 0 ),                    // Trans 2 ambient, Trans 1 ambient - NONE, or the program drifts

        EZWG.createPackedU32_16( STAD.ent_super_auto_builder_death, STAD.ent_super_auto_builder_death ),   // Badness result, Goodness result
        EZWG.createPackedU32_16( 0, 0 ),                    // Trans 2 result, Trans 1 result

        EZWG.createPackedU32( 0, 0, 0, 0 ),                 // TYPE OF TRANSOFRM, trans 2, trans 1, bad, good
                                                            // 0 = self transofmr, 1 = random direction spawn, 2=random direction spawn NO TEAM,     3 = inherit velocity..., 4=damage yurself on spawn from OWN power

        EZWG.createPackedU32( 0, 0, 0, 0 ),                 //  -ONE Shot or not (1 yes, 0 is cummulatibve)
        EZWG.createPackedU32_16( CL.BP_UNN_BUILD_COST, 0 ), // BP build cost, drop value every move (unused - the walk decides what it leaves behind)

    ]);
}


