//  = = = = =   THE KING, TELEPORTING   = = = = =
//  What the king is on the cell his teleport relic sent him to, for one loop of its animation,
//  before he is himself again (THE KING'S TELEPORT at the bottom of util/all_ents.js, and the
//  block of that name in src/stimmings_compute.wgsl, which does the moving). ONE row, whatever
//  he was: it CARRIES his cell - the form he was in, his facing, his good, bad and Trans1 - and
//  when its flash runs out the shader puts every one of them back on the cell it expires on.
//
//      NU_KING_TELEPORT_ENT( "ent_...", {animpckge: "leaderteleport", n: "...", d: "..."}, "ent_leader_mainchar", CL.ANIMATION_0FAST )
//
//  kingEnt is whose face it wears to the world, by STAD name - register his row FIRST: his
//  physics, his scent and damage profile and his powers are copied off it, so to everything
//  around the flash this is the king (his vision, his team's signature, the casings he breaks).
//
//  What the rest of the row says, and why. Where the king's own numbers ride while it carries
//  him is the shader's business (THE KING'S TELEPORT - WHAT IT CARRIES): the row is only what
//  the flash itself does.
//
//    TRANS1   the frame clock AND the life. +1 a tick, the animation is ONE_WAY (Trans1 picks
//             the frame), and it fires the tick after the last frame - frameTime x the frame
//             count, less one because a channel fires on > max. Its result is Nothing: the
//             shader makes it what it carried instead, so a teleport force placed by hand, which
//             carries nothing, fades away. Worked out from the sprite folder like NU_VISUAL_ENT,
//             so more frames make a longer teleport with nothing else to change.
//    GOOD     a whip wisp every tick: max CL.PROD_KING_TELEPORT_WISP, +1 a tick, spawned onto a
//             free neighbour (XFORM.SPAWN). The engine aims a spawn one tick and lands it the
//             next, so the shader lets the teleport aim the next one on the very tick one lands
//             (THE KING'S TELEPORT - A WISP EVERY TICK) - one a tick, not one every other.
//    BAD      CL.KING_TELEPORT_HEALTH (0) off a warrior's weakness: one tick beside anything
//             PHYSICS_GAIA_HOSTILE - or beside an enemy warrior, as for anything allegianced -
//             and he falls into ent_king_gravestone, the real grave every form of him leaves.
//             Good and bad both count from 0 every tick - his own are what the cell carries.
//    TRANS2   nothing reaches it (65535, no from-mask, no ambient) - it is where his Trans1 rides.
//    DESIRE   DESIRE_NOTHING. He stands where he landed: WASD and his Q / E do not reach him
//             (the shader forces Q and E only on DESIRE_MAINCHAR / CTRL), and his scent profile
//             wants no func juice to pull him by.
//    FLIP     none, so its sprite never turns - the cell's facing is his, carried.
//    SOUNDS   [ a wisp landing - silent, it is every tick, he fell, he is himself again, - ]
function NU_KING_TELEPORT_ENT( entNameVariable, miobj, kingEnt, frameTime ){
    const kingId = STAD[''+kingEnt];
    const king = ( typeof kingId === 'number' && kingId > 0 ) ? FullEntEntries[ kingId ] : null;
    if( !king ){
        throw new Error('NU_KING_TELEPORT_ENT: "' + kingEnt + '" is not a registered entity - put this line after its NU_ entry');
    }
    const life = frameTime * STAD[""+miobj.animpckge][2] - 1;  // fires the tick after the last frame

    NU_ENT( ""+entNameVariable, [
        ""+miobj.n,                                              //Names
        ""+miobj.d,                                              //Desc
        ["", "sfx_knighter", "sfx_good_sparkle", ""],            // Sounds: a wisp landing (silent), fell, himself again, -
        ""+miobj.animpckge,                                      // Animation package
        king[4],                                                 // Physics flags - the king's own
        EZWG.createPackedU32_16( EZWG.createPackedU16_8( STAD[""+miobj.animpckge][2] ^ CL.ONE_WAY_ANIM, frameTime ), STAD[""+miobj.animpckge][1] ),  // animSize (ONE_WAY), animFreq, animStart
        EZWG.createPackedU32( 0, 0, CL.FREQ_0FAST, DESIR.DESIRE_NOTHING ),// Flippaleprofile (none), [step/anim bits], MoveFreq, Desire

        king[7],                                                 //  Damage Profile ID, Scent Profile ID - the king's

        0,                                  // Goodness from profile    nothing - the good channel is the wisp clock
        PHYSPROFS.STD_WARRIOR_badness,      // Badness from profile     a warrior's weakness
        0,                                  // Trans1 from profile      NOTHING - Trans1 is its life
        0,                                  // Trans2 from profile      NOTHING - his Trans1 rides there

        EZWG.createPackedU32_16( CL.KING_TELEPORT_HEALTH, CL.PROD_KING_TELEPORT_WISP ),  // Badness max, Goodness max
        EZWG.createPackedU32_16( 65535, life ),            // Trans 2 max, Trans 1 max

        king[14],                                          // Badness power, Goodness power - the king's
        king[15],                                          // Trans 2 power, Trans 1 power - the king's

        EZWG.createPackedU32_16( 0, 1 ),                    // Badness ambient, Goodness ambient    (a wisp a tick)
        EZWG.createPackedU32_16( 0, 1 ),                    // Trans 2 ambient, Trans 1 ambient     (the frame, and the life)

        EZWG.createPackedU32_16( STAD.ent_king_gravestone, STAD.ent_ig_whip_wisp ),  // Badness result, Goodness result
        EZWG.createPackedU32_16( 0, 0 ),                    // Trans 2 result, Trans 1 result (Nothing - the shader gives back what it carries)

        EZWG.createPackedU32( XFORM.SELF, XFORM.SELF, XFORM.SELF, XFORM.SPAWN ),     // TYPE OF TRANSOFRM, trans 2, trans 1, bad, good

        EZWG.createPackedU32( 0, 0, 0, 0 ),              //  -ONE Shot or not (1 yes, 0 is cummulatibve)
        EZWG.createPackedU32_16( CL.BP_UNN_BUILD_COST, 0 ),            // BP build cost, drop value every move

    ]);
}



// More based on the VISUAL compoennt 
function NU_VISUAL_ENT( entNameVariable, miobj, frameTime ){
    NU_ENT( ""+entNameVariable, [
        ""+miobj.n,                                              //Names
        ""+miobj.d,                                              //Desc
        ["", "", "", ""],                                       // Sounds
        ""+miobj.animpckge,                                                 // Animation package
        PHYS.PHYSICS_WALL,                                     // Physics flags of the entity
        EZWG.createPackedU32_16( EZWG.createPackedU16_8(STAD[""+miobj.animpckge][2] ^ CL.ONE_WAY_ANIM, frameTime), STAD[""+miobj.animpckge][1] ),  // animSize, animFreq, animStart (16 bytes)
        EZWG.createPackedU32( 0, 0, CL.FREQ_0FAST, DESIR.DESIRE_NOTHING ),// Flippaleprofile, [0x4bit for wind 0x2 bit (0=desynced, 1=synced animations) steppable=0(1=yes)], MoveFreq, Desire
        
        EZWG.createPackedU32_16( 0, STAD.scnt_std_wall ),                    //  Damage Profile ID (max of 65535),Scent Profile ID (max of 65535),
    
        0,                    // Goodness from profile
        0,                    // Badness from profile, 
        0,                    // Trans1 from profile 
        0,                    // Trans2 from profile, 
        
        EZWG.createPackedU32_16( 65535, 65535 ),            // Badness max, Goodness max
        EZWG.createPackedU32_16( 65535, frameTime*(STAD[""+miobj.animpckge][2]) - 1 ),            // Trans 2 max, Trans 1 max
        
        EZWG.createPackedU32_16( 0, 0 ),                    // Badness power, Goodness power (badness amt hurts YOU when spawn of result t ype 4 occured)
        EZWG.createPackedU32_16( 0, 0 ),                    // Trans 2 power, Trans 1 power
    
        EZWG.createPackedU32_16( 0, 0 ),                    // Badness ambient, Goodness ambient
        EZWG.createPackedU32_16( 0, 1 ),                    // Trans 2 ambient, Trans 1 ambient
    
        EZWG.createPackedU32_16( 0, 0 ),                    // Badness result, Goodness result
        EZWG.createPackedU32_16( 0, 0 ),                    // Trans 2 result, Trans 1 result
    
        EZWG.createPackedU32( 0, 0, 0, 0 ),                 // TYPE OF TRANSOFRM, trans 2, trans 1, bad, good
                                                            // 0 = self transofmr, 1 = random direction spawn, 2=random direction spawn NO TEAM,     3 = inherit velocity..., 4=damage yurself on spawn from OWN power
    
        EZWG.createPackedU32( 0, 0, 0, 0 ),              //  -ONE Shot or not (1 yes, 0 is cummulatibve)
        EZWG.createPackedU32_16( CL.BP_STD_BUILD_COST, 0 ),            // BP build cost, drop value every move
    
    ]);

}
 
// CANT USE THIS - BECAUSE stompable entities are not allowed to transform themselves to death
// THEY can only be stepped on - no movements.. or transformations...  SAD.
 

function NU_STOMPABLE_ENT( entNameVariable, miobj, animFrequ, exactScentId, animationMode ){
    NU_ENT(""+entNameVariable, [ 
        ""+miobj.n,                                              //Names
        ""+miobj.d,                                              //Desc
        ["", "", "", ""],                                       // Sounds
        miobj.animpckge,                                            // ANimatino package
        PHYS.PHYSICS_NULL,                                     // Physics flags of the entity
        EZWG.createPackedU32_16( EZWG.createPackedU16_8(STAD[''+miobj.animpckge][2], animFrequ), STAD[''+miobj.animpckge][1] ), // animSize, animFreq, animStart (16 bytes)
        EZWG.createPackedU32( 0, 1 + ( animationMode.sync?(0^CL.DESYNC_ANIM_BIT):(0) ) + (animationMode.wind?4:0), CL.FREQ_MED, DESIR.DESIRE_NOTHING ),// Flippaleprofile, [0x4bit for wind 0x2 bit (0=desynced, 1=synced animations) steppable=0(1=yes)], MoveFreq, Desire
        
        EZWG.createPackedU32_16( 0, STAD[""+exactScentId] ),                    //  Damage Profile ID (max of 65535),Scent Profile ID (max of 65535),

        0,                    // Goodness from profile
        0,                    // Badness from profile, 
        0,                    // Trans1 from profile 
        0,                    // Trans2 from profile, 
        
        EZWG.createPackedU32_16( 65535, 65535 ),            // Badness max, Goodness max
        EZWG.createPackedU32_16( 65535, 65535 ),            // Trans 2 max, Trans 1 max
        
        EZWG.createPackedU32_16( 0, 0 ),                    // Badness power, Goodness power (badness amt hurts YOU when spawn of result t ype 4 occured)
        EZWG.createPackedU32_16( 0, 0 ),                    // Trans 2 power, Trans 1 power

        EZWG.createPackedU32_16( 0, 0 ),                    // Badness ambient, Goodness ambient
        EZWG.createPackedU32_16( 0, 0 ),                    // Trans 2 ambient, Trans 1 ambient

        EZWG.createPackedU32_16( 0, 0 ),                    // Badness result, Goodness result
        EZWG.createPackedU32_16( 0, 0 ),                    // Trans 2 result, Trans 1 result

        EZWG.createPackedU32( 0, 0, 0, 0 ),                 // TYPE OF TRANSOFRM, trans 2, trans 1, bad, good
                                                            // 0 = self transofmr, 1 = random direction spawn, 2=random direction spawn NO TEAM,     3 = inherit velocity..., 4=damage yurself on spawn from OWN power

        EZWG.createPackedU32( 0, 0, 0, 0 ),                 //  -ONE Shot or not (1 yes, 0 is cummulatibve)
        EZWG.createPackedU32_16( CL.BP_STD_BUILD_COST, 0 ),                    // BP build cost, drop value every move

    ]);
}


