// MAIN CHAR FULL CONTROL 
// Every team's starting king. His good channel is FAITH: it fills only off PHYSICS_FAITH
// neighbours (no key forces it - F used to), and past CL.KING_FAITH_TO_UP_ONE he upgrades
// into ent_leader_up_one_mainchar. Q and E are his abilities. See THE KING'S FORMS at the
// bottom of this file before adding another form of him.
NU_ENT( "ent_leader_mainchar", 
    [
        "The King",                                              //Names
        "This is the king.  Protect or destroy him at all costs.",                                              //Desc
        ["sfx_good_sparkle", "sfx_knighter", "sfx_good_sparkle", "sfx_metal_ting3"],                                       // Sounds  (the first was sfx_audible_ow - the good channel used to fire on hits)
        "leader_mainchar",                                                 // Animation package
        PHYSPROFS.MAINCHAR,                                     // Physics flags of the entity 
        EZWG.createPackedU32_16( EZWG.createPackedU16_8(STAD.leader_mainchar[2], CL.ANIMATION_SFAST), STAD.leader_mainchar[1] ),  // animSize, animFreq, animStart (16 bytes)
        EZWG.createPackedU32( CL.LEFTNRIT_DIR_ANIMS, 0, CL.FREQ_0FAST, DESIR.DESIRE_MAINCHAR ),        // Flippaleprofile, [0x4bit for wind 0x2 bit (0=desynced, 1=synced animations) steppable=0(1=yes)], MoveFreq, Desire
        
        EZWG.createPackedU32_16( 0, STAD.scnt_stim_leader ),                    //  Damage Profile ID (max of 65535),Scent Profile ID (max of 65535),
    
        PHYSPROFS.STD_LEADER_Goodness,          // Goodness from profile    (faith)
        PHYSPROFS.TYPICAL_STIM_badness,    // Badness from profile, 
        0,                    // Trans1 from profile 
        0,                    // Trans2 from profile, 
        
        EZWG.createPackedU32_16( CL.STRONG_HEALTH, CL.KING_FAITH_TO_UP_ONE ),  // Badness max, Goodness max
        EZWG.createPackedU32_16( 65535, 65535 ),            // Trans 2 max, Trans 1 max
        
        EZWG.createPackedU32_16( CL.LDR_PWR_STD, 3 ),       // Badness power, Goodness power (badness amt hurts YOU when spawn of result t ype 4 occured)
        EZWG.createPackedU32_16( 3, 3 ),                    // Trans 2 power, Trans 1 power
    
        EZWG.createPackedU32_16( 0, 0 ),                    // Badness ambient, Goodness ambient
        EZWG.createPackedU32_16( 0, 0 ),                    // Trans 2 ambient, Trans 1 ambient
    
        EZWG.createPackedU32_16( STAD.ent_king_gravestone, STAD.ent_leader_up_one_mainchar ),                    // Badness result, Goodness result
        EZWG.createPackedU32_16( STAD.ent_sprout_turnip_to_mainchar, STAD.ent_mainchar_reasonableman ),                    // Trans 2 result, Trans 1 result
    
        EZWG.createPackedU32( 0, 0, 0, 0 ),     // TYPE OF TRANSOFRM, trans 2, trans 1, bad, good
                                                // 0 = self transofmr, 1 = spawn one ( ADDS one to trans 2, trans 1, bad, good )
    
        EZWG.createPackedU32( 0, 0, 0, 0 ),              //  -ONE Shot or not (1 yes, 0 is cummulatibve)
        EZWG.createPackedU32_16( CL.BP_UNN_BUILD_COST, 0 ),            // BP build cost, drop value every move
    
    ]
    );

