NU_ENT( "ent_reasonableking_cooldownn", [      // TODO is this ent_communicative_old_man?
    "King Reasoning",                                              //Names
    "A king reasoning",                                              //Desc
    ["sfx_good_sparkle", "", "sfx_whoop", ""],                                       // Sounds
    "reasonableman",                                                 // Animation package
    PHYSPROFS.STD_WARRIOR_OPERATCOOLDOWNE,                                     // Physics flags of the entity
    EZWG.createPackedU32_16( EZWG.createPackedU16_8(STAD.reasonableman[2]^ CL.ONE_WAY_ANIM, CL.ANIMATION_0FAST), STAD.reasonableman[1] ),  // animSize, animFreq, animStart (16 bytes)
    EZWG.createPackedU32( 0, 0, CL.FREQ_1FAST, DESIR.DESIRE_NOTHING ),// Flippaleprofile, [0x4bit for wind 0x2 bit (0=desynced, 1=synced animations) steppable=0(1=yes)], MoveFreq, Desire
    
    EZWG.createPackedU32_16( 0, STAD.scnt_warrior_plyr ),                    //  Damage Profile ID (max of 65535),Scent Profile ID (max of 65535),

    0,                    // Goodness from profile
    PHYSPROFS.STD_WARRIOR_badness,  // Badness from profile, 
    0,                    // Trans1 from profile 
    0,                    // Trans2 from profile, 
    
    // Good is the lifetime: one tick per frame of the ONE_WAY animation (fires on > max, hence the -1),
    // so it ends on the last frame however many frames the package has. Trans1 is ONLY the frame clock -
    // 65535 so it can never fire, its result is 0 (Nothing) and firing would delete the king.
    EZWG.createPackedU32_16( CL.WEAK_HEALTH, CL.ANIMATION_0FAST * STAD.reasonableman[2] - 1 ),  // Badness max, Goodness max
    EZWG.createPackedU32_16( 65535, 65535 ),            // Trans 2 max, Trans 1 max
    
    EZWG.createPackedU32_16( 1, 1 ),                    // Badness power, Goodness power (badness amt hurts YOU when spawn of result t ype 4 occured)
    EZWG.createPackedU32_16( 0, 0 ),                    // Trans 2 power, Trans 1 power

    EZWG.createPackedU32_16( 0, 1 ),                    // Badness ambient, Goodness ambient
    EZWG.createPackedU32_16( 0, 1 ),                    // Trans 2 ambient, Trans 1 ambient (drives the frame)

    EZWG.createPackedU32_16( STAD.ent_king_gravestone, STAD.ent_leader_mainchar  ),// Badness result, Goodness result
    EZWG.createPackedU32_16( 0, 0 ),                    // Trans 2 result, Trans 1 result

    EZWG.createPackedU32( 0, 0, 0, 0 ),                 // TYPE OF TRANSOFRM, trans 2, trans 1, bad, good
                                                        // 0 = self transofmr, 1 = random direction spawn, 2=random direction spawn NO TEAM,     3 = inherit velocity..., 4=damage yurself on spawn from OWN power

    EZWG.createPackedU32( 0, 0, 0, 0 ),              //  -ONE Shot or not (1 yes, 0 is cummulatibve)
    EZWG.createPackedU32_16( CL.BP_UNN_BUILD_COST, 0 ),            // BP build cost, drop value every move

]); 



