//  = = = = = = = = =   THE KING'S UPGRADES   = = = = = = = = =
//  A king's good channel is his FAITH - PHYSICS_FAITH neighbours (a faith orb altar, a faith
//  runner) fill it, nothing else does - and filling it upgrades him, for the rest of the level:
//      ent_leader_mainchar         past CL.KING_FAITH_TO_UP_ONE   ->  ent_leader_up_one_mainchar
//      ent_leader_up_one_mainchar  past CL.KING_FAITH_TO_UP_TWO   ->  ent_leader_up_two_mainchar
//      ent_leader_up_two_mainchar  past CL.KING_FAITH_UP_TWO_MAX  ->  himself again, for now
//  Each upgraded king is the base king's row with his own sprite and his own next step, and
//  each has his own copy of the Q form (the sprout) and the E forms (the reasonable king and
//  its cooldown), because those have to grow back into the king who used them. (His teleport
//  needs no copy: it carries whichever form he is in - THE KING'S TELEPORT, the end of this file.)
//
//  Every step is a SELF transform (type 0), like his abilities and his death: he does not move
//  on the tick he changes, he keeps his team and his highlight, and he starts the new form with
//  every channel at 0 - his health included.
//
//  ⚠ APPEND ONLY - ids are array indices. Every living form here is listed in KING_FORMS below.

// THE KING, UPGRADED ONCE
NU_ENT( "ent_leader_up_one_mainchar",
    [
        "The King +",                                              //Names
        "The king upgraded by faith.",                                              //Desc
        ["sfx_good_sparkle", "sfx_knighter", "sfx_good_sparkle", "sfx_metal_ting3"],                                       // Sounds
        "leader_up_one_mainchar",                                                 // Animation package
        PHYSPROFS.MAINCHAR,                                     // Physics flags of the entity
        EZWG.createPackedU32_16( EZWG.createPackedU16_8(STAD.leader_up_one_mainchar[2], CL.ANIMATION_SFAST), STAD.leader_up_one_mainchar[1] ),  // animSize, animFreq, animStart (16 bytes)
        EZWG.createPackedU32( CL.LEFTNRIT_DIR_ANIMS, 0, CL.FREQ_0FAST, DESIR.DESIRE_MAINCHAR ),        // Flippaleprofile, [0x4bit for wind 0x2 bit (0=desynced, 1=synced animations) steppable=0(1=yes)], MoveFreq, Desire

        EZWG.createPackedU32_16( 0, STAD.scnt_stim_leader ),                    //  Damage Profile ID (max of 65535),Scent Profile ID (max of 65535),

        PHYSPROFS.STD_LEADER_Goodness,          // Goodness from profile    (faith)
        PHYSPROFS.TYPICAL_STIM_badness,    // Badness from profile,
        0,                    // Trans1 from profile
        0,                    // Trans2 from profile,

        EZWG.createPackedU32_16( CL.STRONG_HEALTH, CL.KING_FAITH_TO_UP_TWO ),  // Badness max, Goodness max
        EZWG.createPackedU32_16( 65535, 65535 ),            // Trans 2 max, Trans 1 max

        EZWG.createPackedU32_16( CL.LDR_PWR_STD, 3 ),       // Badness power, Goodness power (badness amt hurts YOU when spawn of result t ype 4 occured)
        EZWG.createPackedU32_16( 3, 3 ),                    // Trans 2 power, Trans 1 power

        EZWG.createPackedU32_16( 0, 0 ),                    // Badness ambient, Goodness ambient
        EZWG.createPackedU32_16( 0, 0 ),                    // Trans 2 ambient, Trans 1 ambient

        EZWG.createPackedU32_16( STAD.ent_king_gravestone, STAD.ent_leader_up_two_mainchar ),                    // Badness result, Goodness result
        EZWG.createPackedU32_16( STAD.ent_sprout_turnip_to_up_one_mainchar, STAD.ent_up_one_mainchar_reasonableman ),                    // Trans 2 result, Trans 1 result

        EZWG.createPackedU32( 0, 0, 0, 0 ),     // TYPE OF TRANSOFRM, trans 2, trans 1, bad, good
                                                // 0 = self transofmr, 1 = spawn one ( ADDS one to trans 2, trans 1, bad, good )

        EZWG.createPackedU32( 0, 0, 0, 0 ),              //  -ONE Shot or not (1 yes, 0 is cummulatibve)
        EZWG.createPackedU32_16( CL.BP_UNN_BUILD_COST, 0 ),            // BP build cost, drop value every move

    ]
    );

