//  = = = = = = = = =   THE KING'S FORMS   = = = = = = = = =
//  Everything a team's king can be while he is alive, in ONE list. He self-transforms from form
//  to form - his Q and E, his upgrades - and in every one of them he is still his team's king,
//  so every check that asks "is this cell the king?" is built from this list and nothing else:
//      stimmings_compute.wgsl   WAS THIS CELL A KING WHEN THE TICK BEGAN (so a death in any
//                               form leaves his REAL grave), KING MODE, KING POSITION GOES OUT
//      Ex9_Stimmings2.js        seedCensusFromLoadedGrid(), finding the kings on a loaded grid
//  The gravestone is not on it - it is what he leaves behind, and the one check that wants it
//  too (the king mode highlight) names it itself.
//
//  ⚠ A NEW FORM OF THE KING GOES IN HERE, or while he wears it he drops out of the camera, the
//  save and king mode, and his death in it leaves a gravestone nobody counts as his. Nothing else
//  is needed for him to teleport in it - the teleport carries whatever form he is in by its place
//  on this list (THE KING'S TELEPORT, the end of this file), as long as the form counts nothing in
//  Trans2 and the list stays under 256: KING_TELEPORT_CHECK() stops the build if not.
//
//  The last is a row from the END of this file (ids only append). The bundle runs this file with
//  STAD already holding every id util/scruncher.js wrote to animation_lookups.js, so naming it up
//  here resolves the same way a row dying into a later entity does.
var KING_FORMS = [
    STAD.ent_leader_mainchar,                       // every team starts as this king
    STAD.ent_sprout_turnip_to_mainchar,             //      his Q, regrowing
    STAD.ent_mainchar_reasonableman,                //      his E
    STAD.ent_reasonableking_cooldownn,              //      his E, cooling down
    STAD.ent_leader_up_one_mainchar,                // upgraded once
    STAD.ent_sprout_turnip_to_up_one_mainchar,
    STAD.ent_up_one_mainchar_reasonableman,
    STAD.ent_up_one_reasonableking_cooldownn,
    STAD.ent_leader_up_two_mainchar,                // upgraded twice
    STAD.ent_sprout_turnip_to_up_two_mainchar,
    STAD.ent_up_two_mainchar_reasonableman,
    STAD.ent_up_two_reasonableking_cooldownn,
    STAD.ent_king_teleport                          // teleporting, carrying whichever of these he was
];

//  KING_FORMS as a WGSL test of the u32 named v:   ( v == 137u || v == 437u || ... )
//  The compute shader is a JS template literal, so it splices this in where it needs one.
function KING_FORM_WGSL( v ){
    return '( ' + KING_FORMS.map( function( ent ){ return v + ' == ' + ent + 'u'; } ).join( ' || ' ) + ' )';
}



