//  = = = = = = = = =   THE KING'S TELEPORT   = = = = = = = = =
//  ent_relic_king_teleport (the tier 5 pool, RELIC_POOLS in Ex9_Stimmings2.js) is the one relic
//  that is never put on the map. Dropped on a cell, it moves the DROPPING TEAM'S KING there in a
//  single tick: the cell he stands on empties and the drop cell becomes ent_king_teleport, which
//  CARRIES THE CONTENTS OF HIS CELL - whichever form of him it was (any rank, his sprout, his
//  reasonable king, a teleport already under way), his facing, his good (his faith), his bad
//  (the hurt he has taken) and his Trans1 (an ability's clock). It stands through one loop of
//  the leaderteleport animation throwing off a whip wisp a tick, and on the tick it expires the
//  cell becomes exactly what his cell held when he left it (NU_KING_TELEPORT_ENT in
//  entity_templater.js, THE KING'S TELEPORT - WHAT IT CARRIES in the compute shader).
//
//  The move is THE KING'S TELEPORT in src/stimmings_compute.wgsl. Both of the cells it changes
//  decide it off the SAME numbers - the start of the tick and this team's input block - so
//  either both change or neither does, and there is never a tick with no king or with two:
//
//      the drop cell     the relic drop's own slots: RELIC_X / RELIC_Y
//      the king's cell   KING_X / KING_Y in the same block, which the page fills in on the tick
//                        the drop goes out, off the king word of the pass just read back -
//                        exact, because no pass ever runs before its predecessor's readback is
//                        handled. The shader checks it anyway: that cell must hold a living form
//                        of this team's king, or the drop is refused (verdict 5) and handed back
//
//  Both are logged inputs, so a replay moves him on the same tick to the same cell, and a save
//  taken on any tick of it is the grid alone: the teleport's cell is what carries him.
//
//  Its row has bad result 0: should the relic itself ever stand on the map (an ADMIN force
//  place), its activation fuse runs out into nothing. Its card is its own animation.
NU_RELIC_ACTION_ENT("ent_relic_king_teleport",  0,  {animpckge: "leaderteleport", n:"King's Teleport",
    d:"Relic that sends your king to the cell it lands on - he arrives in a flash of light throwing off whip wisps, and is himself again when it fades, exactly as he left. Anything hostile that touches him before then kills him.",
    sfx: { drop: "sfx_alien_bowwmm", activate: "sfx_one_subtle_bang" }},
    CL.ANIMATION_0FAST, {sync: false, wind: false} );

// The king, teleporting - ONE row whatever he was: it carries his cell and gives it back.
NU_KING_TELEPORT_ENT( "ent_king_teleport",  {animpckge: "leaderteleport", n:"The King - Teleporting",
    d:"The king inside the flash of his teleport. When it fades he is himself again, exactly as he left - one touch of anything hostile before that and he falls."
    },
    "ent_leader_mainchar", CL.ANIMATION_0FAST );

//  WHAT IT CARRIES IT CARRIES BY PLACE. The form he was in rides in the 8 bits of the teleport
//  cell's lastCmdDetail as its place on KING_FORMS + 1 (0 carries nothing), and his Trans1 in its
//  Trans2. That costs two promises, and KING_TELEPORT_CHECK() holds the build to both (it runs
//  in util/king_hud_sheet.js, and again when the game builds its compute shader):
//
//      KING_FORMS has at most 255 forms on it               - the place + 1 fits 8 bits
//      no form of him but the teleport counts anything      - so his Trans2 is always 0, and
//        in Trans2 (no from-mask, no ambient)                 nothing is lost not carrying it
//      every form of him steers as the king does or not     - DESIRE_MAINCHAR / CTRL / NOTHING,
//        at all                                               none of which reads lastCmdDetail
//
//  and the teleport has to be on KING_FORMS itself, so it is tracked as him - and so a teleport
//  begun before another has faded carries on carrying what the first one did.
function KING_TELEPORT_CHECK(){
    var name = function( id ){ return ( FullEntEntries[ id ] ? FullEntEntries[ id ][0] : 'entity ' + id ); };
    var teleport = STAD.ent_king_teleport;
    if( KING_FORMS.length > 255 ){
        throw new Error( 'THE KING\'S TELEPORT: KING_FORMS has ' + KING_FORMS.length + ' forms - the teleport carries one in 8 bits, so 255 at most (all_ents.js)' );
    }
    if( KING_FORMS.indexOf( teleport ) < 0 ){
        throw new Error( 'THE KING\'S TELEPORT: ent_king_teleport has to be on KING_FORMS, or the king is untracked inside it (all_ents.js)' );
    }
    KING_FORMS.forEach( function( form, n ){
        var row = FullEntEntries[ form ];
        if( !row || KING_FORMS.indexOf( form ) !== n ){
            throw new Error( 'THE KING\'S TELEPORT: KING_FORMS[' + n + '] is ' + name( form ) + ' - every entry a real entity, each once (all_ents.js)' );
        }
        var desire = row[6] & 63;
        if( desire !== DESIR.DESIRE_MAINCHAR && desire !== DESIR.DESIRE_CTRL && desire !== DESIR.DESIRE_NOTHING ){
            throw new Error( 'THE KING\'S TELEPORT: ' + name( form ) + ' has a desire that reads lastCmdDetail, where the teleport keeps the form it carries' );
        }
        if( form !== teleport && ( ( row[11] >>> 0 ) !== 0 || ( ( row[17] >>> 16 ) & 0xFFFF ) !== 0 ) ){
            throw new Error( 'THE KING\'S TELEPORT: ' + name( form ) + ' counts something in Trans2, which the teleport does not carry' );
        }
    });
}

//  For the compute shader, which splices these in the way it does KING_FORM_WGSL: the place + 1
//  on KING_FORMS of the u32 named v (0u - nothing - if it is not a form of the king), and the
//  form at place + 1 i (0u, Nothing, for 0 or past the end).
function KING_FORM_PLACE_WGSL( v ){
    KING_TELEPORT_CHECK();
    var s = '0u';
    KING_FORMS.forEach( function( ent, n ){ s = 'select( ' + s + ', ' + ( n + 1 ) + 'u, ' + v + ' == ' + ent + 'u )'; } );
    return s;
}
function KING_FORM_AT_WGSL( i ){
    var s = '0u';
    KING_FORMS.forEach( function( ent, n ){ s = 'select( ' + s + ', ' + ent + 'u, ' + i + ' == ' + ( n + 1 ) + 'u )'; } );
    return s;
}



