var ScentProfiles = [];
// WISDOM (the 2nd value of the "HOPE, WISDOM, PROCESSING, GAIAHOME" packs) is not a
// plain 0-255 scent in the cells: it is 2 team bits over a 0-63 value, and its only
// source is the player's 'r' marker. Its DECAY here is used literally (subtracted
// from the 0-63 value, so 255 still blocks it). Its EMISSION is not read at all.
// See encyclopedia/03-scents-and-damage.md, "WISDOM is packed differently".
function NU_SCNT( variableString, entireDef){
    STAD[''+variableString] = ScentProfiles.length;
    ScentProfiles.push(
        entireDef
    );
}

