//  = = = = =   BLUEPRINTS - THE WALKS A SUPER AUTO BUILDER TAKES   = = = = =
//  A super auto builder (ent_super_auto_builder) builds a blueprint by walking it, one cell a
//  step, and everything it needs to know about the walk is here, so it costs the compute
//  shader one or two reads a tick (THE SUPER AUTO BUILDER in stimmings_compute.wgsl). The
//  walk is each blueprint's build order: util/scruncher.js baked it into util/all_bps.js as
//  ALLBPS[n].path - cell indices (row * width + col) in visit order - from the blueprint's
//  pathway file, or the default spiral out from the middle (util/bp_pathways.js).
//
//  Appended LAST, after the background, so every offset before it is exactly where it was.
//  Needs ALLBPS, which is why Ex9_Stimmings2.js places the blueprints ABOVE this file.
//
//  THE DIRECTORY - SCHEMA_INDEX.bp_dir_chunk words per blueprint SLOT, at
//  bp_start + slot * bp_dir_chunk. Slot 0 is "no blueprint" and all zero; slot s is ALLBPS[s-1]
//  (the same 1-based slot a builder carries in its Trans1 - BP_SLOT below names them):
//
//      + 0   where its steps start, counted from bp_start
//      + 1   width (lo16) | height (hi16)
//      + 2   how many steps the walk has (= width * height; 0 = no walk at all)
//      + 3   the cell the walk starts on: column (lo16) | row (hi16), row 0 = the TOP row
//
//  THE STEPS - one u32 per step k of the walk:
//
//      bits  0-15   the blueprint's entity on the cell the walk is on at step k - what the
//                   builder leaves there when it steps off it (or turns into, on the last)
//      bits 16-19   which way the NEXT cell is, as the compute shader's 3x3 neighbour index
//                   (dx = -1 + d%3, dy = -1 + d/3, y UP the screen): 4 = no next cell, this
//                   is the last step
//      bits 20-31   0
//
//  Row 0 of a blueprint is the TOP of the picture and EZY counts UP the screen, so one row
//  down the blueprint is dy = -1 - the same way up STIMMINGS_MAP_GEN.stampBp lays a stamp, so
//  a walked blueprint and a stamped one come out the same.
//
//  THE PROGRAMS - SCHEMA_INDEX.sab_prog_start, one u32 per ENTITY TYPE: the Trans1 / Trans2
//  points that entity hands the super auto builder it activates into -
//  createPackedU32_16( start step, slot ) - and 0 for every entity that hands over nothing.
//  Filled from SUPER_AUTO_BUILDER_PROGRAM in util/all_ents.js.
//
//  ⚠ A SLOT IS AN ALLBPS INDEX, AND ALLBPS IS ORDERED BY FILE NAME. A blueprint file whose name
//  sorts in ahead of another moves that one's slot up by one, so a builder in a SAVE that was
//  walking it would walk its neighbour after a rebuild. Same hazard mapgen's blueprint indices
//  have always had (util/scruncher.js); a replay is unaffected - it rebuilds from the seed.
SCHEMA_INDEX.bp_dir_chunk = 4;

var BP_SLOT = {};                   // blueprint name -> the slot a builder carries in Trans1
var BP_PACKED = ( typeof ALLBPS !== 'undefined' && ALLBPS ) ? ALLBPS : [];
if( BP_PACKED.length === 0 ){
    console.error('STIMMINGS DB: no blueprints to pack - ALLBPS must be placed above the database, see Ex9_Stimmings2.js');
}

SCHEMA_INDEX.bp_count = BP_PACKED.length;
SCHEMA_INDEX.bp_start = 0 + indTracker;

var bpDirectory = new Array( (BP_PACKED.length + 1) * SCHEMA_INDEX.bp_dir_chunk ).fill( 0 );
var bpSteps = [];

for(let s = 1; s <= BP_PACKED.length; s++){
    const bp = BP_PACKED[ s - 1 ];
    const walk = Array.isArray( bp.path ) ? bp.path : [];
    BP_SLOT[ bp.name ] = s;

    if( walk.length === 0 ){
        // util/all_bps.js from before build orders existed, or a blueprint the scruncher
        // could not give a walk to - a builder handed this slot just stands still.
        console.error('STIMMINGS DB: blueprint ' + bp.name + ' has no build order - run stim.bat');
    }

    const at = s * SCHEMA_INDEX.bp_dir_chunk;
    bpDirectory[ at + 0 ] = bpDirectory.length + bpSteps.length;
    bpDirectory[ at + 1 ] = EZWG.createPackedU32_16( bp.height, bp.width );
    bpDirectory[ at + 2 ] = walk.length;
    bpDirectory[ at + 3 ] = walk.length ? EZWG.createPackedU32_16( Math.floor( walk[0] / bp.width ), walk[0] % bp.width ) : 0;

    for(let k = 0; k < walk.length; k++){
        const here = walk[k];
        const ent = ( bp.data[ here ] | 0 ) & 0x0000FFFF;      // an unknown key in the file is null - nothing
        let next = 4;
        if( k + 1 < walk.length ){
            const dc = ( walk[k + 1] % bp.width ) - ( here % bp.width );
            const dr = Math.floor( walk[k + 1] / bp.width ) - Math.floor( here / bp.width );
            if( dc >= -1 && dc <= 1 && dr >= -1 && dr <= 1 && !( dc === 0 && dr === 0 ) ){
                next = ( dc + 1 ) + 3 * ( 1 - dr );             // dy = -dr: row 0 is the top
            }
        }
        bpSteps.push( ( ( next & 0x0000000F ) << 16 ) | ent );
    }
}

totalbuffer = totalbuffer.concat( bpDirectory, bpSteps );
indTracker += bpDirectory.length + bpSteps.length;

//  THE PROGRAMS
var sabPrograms = new Array( FullEntEntries.length ).fill( 0 );
var SAB_PROGRAM_LIST = ( typeof SAB_PROGRAMS !== 'undefined' ) ? SAB_PROGRAMS : [];
for(let p = 0; p < SAB_PROGRAM_LIST.length; p++){
    const prog = SAB_PROGRAM_LIST[p];
    const slot = BP_SLOT[ prog.bp ] | 0;
    if( slot < 1 ){
        console.error('STIMMINGS DB: ' + prog.ent + ' builds ' + prog.bp + ', which is not a blueprint - its builder will stand still');
        continue;
    }
    sabPrograms[ prog.id ] = EZWG.createPackedU32_16( prog.step, slot );
}

SCHEMA_INDEX.sab_prog_start = 0 + indTracker;
totalbuffer = totalbuffer.concat( sabPrograms );
indTracker += sabPrograms.length;



