// Perlin noise
class PerlinNoise {
    constructor( rnd ) {
        this.perm = [...Array( 256 )].map(() => Math.floor(rnd.random() * 255));
        this.perm = this.perm.concat(this.perm); // Duplicate to avoid buffer overflow
    }

    fade(t) {
        return t * t * t * (t * (t * 6 - 15) + 10);
    }

    lerp(t, a, b) {
        return a + t * (b - a);
    }

    grad(hash, x, y) {
        const h = hash & 15;
        const u = h < 8 ? x : y;
        const v = h < 4 ? y : h === 12 || h === 14 ? x : 0;
        return ((h & 1) === 0 ? u : -u) + ((h & 2) === 0 ? v : -v);
    }

    noise(x, y) {
        const X = Math.floor(x) & 255;
        const Y = Math.floor(y) & 255;

        x -= Math.floor(x);
        y -= Math.floor(y);

        const fadeX = this.fade(x);
        const fadeY = this.fade(y);

        const p0 = this.perm[X] + Y;
        const p00 = this.perm[p0];
        const p01 = this.perm[p0 + 1];
        const p1 = this.perm[X + 1] + Y;
        const p10 = this.perm[p1];
        const p11 = this.perm[p1 + 1];

        const grad00 = this.grad(p00, x, y);
        const grad10 = this.grad(p10, x - 1, y);
        const grad01 = this.grad(p01, x, y - 1);
        const grad11 = this.grad(p11, x - 1, y - 1);

        return this.lerp(
            fadeY,
            this.lerp(fadeX, grad00, grad10),
            this.lerp(fadeX, grad01, grad11)
        );
    }

// You can add additional functions for 3D or 4D Perlin noise if needed
}

 
// Required for entity interaction

var STIMMINGS_MAP_GEN = {};

STIMMINGS_MAP_GEN.PLAYER_ZERO_ID = 0;
STIMMINGS_MAP_GEN.PLAYER_ONE_ID = 1;
STIMMINGS_MAP_GEN.ENEMY_TEAM_ID = 2;

STIMMINGS_MAP_GEN.getWhitePixels = function( canvas, img ){

    let ctx = canvas.getContext( '2d' );

    canvas.width = img.width;
    canvas.height = img.height;
    ctx.drawImage(img, 0, 0, img.width, img.height);

    // Get image data
    var imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    var data = imageData.data;

    var whitePixelCoordinates = [];

    // Loop through the image data to find white pixels
    for (var i = 0; i < data.length; i += 4) {
        var red = data[i];
        var green=data[i + 1];
        var blue= data[i + 2];

        // Check if the pixel is white (255, 255, 255)
        if (red === 255 && green === 255 && blue === 255) {
            var x = (i / 4) % canvas.width;
            var y = Math.floor((i / 4) / canvas.width);
            whitePixelCoordinates.push({ x: x, y: y });
        }
    }

    return whitePixelCoordinates;
};


STIMMINGS_MAP_GEN.uniqueColoursAndCubeMap = function( canvas, dbEntry ){


    let ctx = canvas.getContext( '2d' );
    canvas.width = 8;
    canvas.height = 8;

    let listOf2DSlices = [];

    let theNuMap = [];
    let allUniqCols = [];

    if(dbEntry.animation){
        let animLookup = ""+dbEntry.animation;
        animLookup = gol[animLookup];
    
        let listOfImages = [];
        if( animLookup.animOffset ){
            for(let u = 0;u < animLookup.anims.length;u+=2){
                listOfImages.push( animLookup.anims[u] );
            } 
        }
        else{
            listOfImages.push( animLookup );
        }
 
        // Loop through each image and compule it into a 2d array of colours
        // [x][y] = {r:22, g: 44, b: 63, a: 34}
        for(let d = 0; d < listOfImages.length;d++){
            
            let entirSlic = new Array( canvas.width );
            for(let b = 0;b < entirSlic.length;b++){
                entirSlic[b] = new Array( canvas.height );
            }
            
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.drawImage(listOfImages[d], 0, 0, listOfImages[d].width, listOfImages[d].height);
            let imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
            let data = imageData.data;

            for (let i = 0; i < data.length; i += 4) {
                let red = data[i];
                let green = data[i + 1];
                let blue = data[i + 2];
                let alph = data[i + 3]; 

                  
                // Check for a colour match
                let currColIndMatch = -1;
                if(alph > 0 ){
                    for(let a = 0;a < allUniqCols.length;a++){
                        if( allUniqCols[a].r === red && allUniqCols[a].g === green && allUniqCols[a].b === blue ){
                            currColIndMatch = a;
                        }
                    }
                    // Need to make new colour
                    if( currColIndMatch === -1 ){
                        allUniqCols.push({r: red, g: green, b: blue});
                        theNuMap.push(allUniqCols.length);
                    }
                    else{
                        theNuMap.push(currColIndMatch+1)
                    }

                }
                else{
                    theNuMap.push(0);
                }

                

                // Check if the pixel is white (255, 255, 255) 
                 
            }

            listOf2DSlices.push(
                entirSlic
            );

        }
 
    }

    return {l: listOf2DSlices, nm: theNuMap, cols:allUniqCols};
    
 
};

STIMMINGS_MAP_GEN.get4DCubeArray = function( canvas, dbEntry ){

    let ctx = canvas.getContext( '2d' );
    canvas.width = 8;
    canvas.height = 8;

    let listOf2DSlices = [];

    if(dbEntry.animation){
        let animLookup = ""+dbEntry.animation;
        animLookup = gol[animLookup];
    
        let listOfImages = [];
        if( animLookup.animOffset ){
            for(let u = 0;u < animLookup.anims.length;u+=2){
                listOfImages.push( animLookup.anims[u] );
            } 
        }
        else{
            listOfImages.push( animLookup );
        }
 
        // Loop through each image and compule it into a 2d array of colours
        // [x][y] = {r:22, g: 44, b: 63, a: 34}
        for(let d = 0; d < listOfImages.length;d++){
            
            let entirSlic = new Array( canvas.width );
            for(let b = 0;b < entirSlic.length;b++){
                entirSlic[b] = new Array( canvas.height );
            }
            
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.drawImage(listOfImages[d], 0, 0, listOfImages[d].width, listOfImages[d].height);
            let imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
            let data = imageData.data;

            for (let i = 0; i < data.length; i += 4) {
                let red =  data[i];
                let green =data[i + 1];
                let blue = data[i + 2];
                let alph = data[i + 3]; 
                // Check if the pixel is white (255, 255, 255) 
                var x = (i / 4) % canvas.width;
                var y = Math.floor((i / 4) / canvas.width);
                entirSlic[x][y] = {
                    r: red, g: green, b: blue, a: alph
                };
            }

            listOf2DSlices.push(
                entirSlic
            );

        }
 
    }

    return listOf2DSlices;
    
 
};




STIMMINGS_MAP_GEN.getBpByName = function(nameVal){
    for(let n = 0;n < ALLBPS.length;n++){
        if(ALLBPS[n].name === nameVal){
            return ALLBPS[n];
        }
    }
    return null;
};


// ── WHERE THE FOUR TEAMS START ──────────────────────────────────────────────
//
// Written in SCREEN coordinates, the way you look at the map:
//
//        fx   0 = left edge,  1 = right edge
//        fy   0 = TOP edge,   1 = bottom edge
//
//        team 1 (blue)   TOP LEFT          team 2   TOP RIGHT
//        team 3          BOTTOM LEFT       team 4   BOTTOM RIGHT
//
// A FRACTION of the map, not a cell count, so the table survives a change of
// CHUNK_SIZE. 0.335 puts a base a third of the way in from its own two edges:
// far enough off the rim to have room to grow behind it, far enough off the
// middle that the centre of the map belongs to nobody. The other three corners
// are the SAME inset measured from the far side, so the four are exact mirror
// images about the centre and every team is equidistant from the middle, from
// its two neighbours, and from the one diagonally opposite. Work the far corner
// out as (glength - near), never floor((1-f)*glength), which is off by one
// whenever f*glength is not a whole number and quietly breaks that symmetry.
//
// ⚠ THE BUFFER DOES NOT USE THOSE AXES. This is the ONE place the difference is
// dealt with, because three separate spaces meet here:
//
//    mapgen   initialState[ xx*glength + yy ]
//    shader   EZ_STATE_IN[ EZY*grid.x + EZX ]     =>  xx IS EZY,  yy IS EZX
//    screen   EZX runs RIGHT.  EZY runs UP  - stimmings_fragment.wgsl line 142,
//             worldYf = CELLS_ACROSS_Y - (fragCoord.y+1)/pxPerCell + yPan
//
// which gives, for a spawn written as (fx, fy) above:
//
//    EZX = fx * glength           EZY = glength - fy * glength
//    yy  = EZX                    xx  = EZY
//
// Get ANY of those backwards and the compounds land in the wrong corners with
// the wrong colours in them - which looks exactly like the teams not being
// applied at all, rather than like a flipped axis.
STIMMINGS_MAP_GEN.SPAWN_INSET_FRAC = 0.335;

// Team 1 is the session's own start and gets the human compound (a leader, the
// keycap tutorial and the auto-miner rig, all of which want a player):
// util/all_bps/19_14_nustart7063.txt. Teams 2-4 get the bigger AI compound,
// which has the two things that make it start ITSELF:
// see util/all_bps/27_28_aistart28292.txt.
STIMMINGS_MAP_GEN.PLAYER_SPAWN_BP = 'bp_nustart7063';
STIMMINGS_MAP_GEN.AI_SPAWN_BP     = 'bp_aistart28292';

// The old human compound. Nobody spawns in it any more, but it still has a
// leader in it, so it stays out of the scatter like the live two.
STIMMINGS_MAP_GEN.RETIRED_SPAWN_BP = 'bp_betterstart28291';

// Is this one of the starting compounds? The random-structure scatter has
// to skip all of them - a spare town centre with a leader asleep in it, owned
// by nobody, is not a decoration.
STIMMINGS_MAP_GEN.isSpawnBp = function( nameVal ){
    return nameVal === STIMMINGS_MAP_GEN.PLAYER_SPAWN_BP
        || nameVal === STIMMINGS_MAP_GEN.AI_SPAWN_BP
        || nameVal === STIMMINGS_MAP_GEN.RETIRED_SPAWN_BP;
};

// The four anchors, resolved to cells in EVERY space that needs them, each
// already backed off by half its own blueprint so the fraction names the MIDDLE
// of the compound rather than one of its corners. The reservation pass, the
// placement pass and the opening camera all call this, so there is exactly one
// answer to "where does team N live" and exactly one axis conversion.
//
// Each entry carries:
//    ezx, ezy   screen / shader space  - what the camera and the fragment
//               shader think in.  ezx runs right, ezy runs UP.
//    mx,  my    mapgen space, the CENTRE  (mx is the xx axis, my is the yy axis)
//    x,   y     mapgen space, the TOP LEFT to hand to stampBp
STIMMINGS_MAP_GEN.spawnAnchors = function( glength ){

    let near = Math.floor( STIMMINGS_MAP_GEN.SPAWN_INSET_FRAC * glength );
    let far  = glength - near;

    // fx/fy are screen fractions; near/far already carry the 0.335 and 0.665.
    //   ezx = fx*glength           -> near on the left,  far on the right
    //   ezy = glength - fy*glength -> far  at the top,   near at the bottom
    let corners = [
        { team: 1, ezx: near, ezy: far,  bp: STIMMINGS_MAP_GEN.PLAYER_SPAWN_BP },  // TOP LEFT
        { team: 2, ezx: far,  ezy: far,  bp: STIMMINGS_MAP_GEN.AI_SPAWN_BP },      // TOP RIGHT
        { team: 3, ezx: near, ezy: near, bp: STIMMINGS_MAP_GEN.AI_SPAWN_BP },      // BOTTOM LEFT
        { team: 4, ezx: far,  ezy: near, bp: STIMMINGS_MAP_GEN.AI_SPAWN_BP }       // BOTTOM RIGHT
    ];

    let out = [];
    for(let s = 0;s < corners.length;s++){
        let c = corners[s];
        let beepee = STIMMINGS_MAP_GEN.getBpByName( c.bp );
        // A missing blueprint is a build problem (a renamed or unscrunched
        // .txt), not a map problem - say so and let the other teams spawn.
        if( !beepee ){
            console.log('MAPGEN: spawn blueprint missing, team ' + c.team + ' has nowhere to live:', c.bp);
            continue;
        }
        // THE ONE CONVERSION. mapgen xx is the shader's EZY; mapgen yy is EZX.
        let mx = c.ezy;
        let my = c.ezx;
        out.push({
            team: c.team,
            bp: beepee,
            ezx: c.ezx,
            ezy: c.ezy,
            mx: mx,
            my: my,
            x: STIMMINGS_MAP_GEN.wrap( mx - Math.floor(beepee.height/2), glength ),
            y: STIMMINGS_MAP_GEN.wrap( my - Math.floor(beepee.width/2),  glength )
        });
    }
    return out;
};

// How far out from a spawn's middle the ground is cleared for it. Big enough to
// clear the biggest compound's footprint (the AI's 27x28) and leave an apron around it.
STIMMINGS_MAP_GEN.SPAWN_APRON_R = 34;

// The one place a blueprint becomes cells. Both the random scatter and the four
// team spawns come through here so they cannot drift apart over the row/column
// swap in the middle of it, which is worth stating plainly because it catches
// everybody:
//
//   this file indexes (xx*glength + yy)   the shader indexes (EZY*grid.x + EZX)
//   => mapgen xx IS the shader's EZY,     mapgen yy IS the shader's EZX
//
// So a blueprint's COLUMN walks the shader's X, and its ROW walks the shader's
// Y - backwards, via (height - row), because EZY counts UP the screen and a
// blueprint file reads down it. Row 0 of the .txt is the top of the picture.
// (This is a TRANSPOSE. It is not the GRID_SIZE-1-y flip in pitfall 16 - that
// one belongs to the mouse's dragStartY convention, a different space again.)
//
// Note it writes the blueprint's ent_nothing cells too - a stamp CLEARS its
// whole rectangle, which is what makes a spawn compound land clean on top of
// whatever the wilds put there.
STIMMINGS_MAP_GEN.stampBp = function( beepee, initialState, glength, attlength, topLeftX, topLeftY, teamm ){
    for(let i = 0;i < beepee.data.length;i++){
        let yy = (glength + topLeftY + ((i%beepee.width)) ) % glength;
        let xx = (glength + topLeftX + (beepee.height-Math.floor(i/beepee.width)) ) % glength;
        STIMMINGS_MAP_GEN.createEntity( beepee.data[i], initialState, glength, attlength, xx, yy, teamm );
    }
};

STIMMINGS_MAP_GEN.wrap = function( v, glength ){
    return ((v % glength) + glength) % glength;
};

// What is standing on this cell right now. Attribute plane 0 starts at offset 0,
// so the plane index drops out; the entity type is its low 16 bits (SLOT0).
STIMMINGS_MAP_GEN.entTypeAt = function( initialState, glength, xx, yy ){
    return initialState[ (xx*glength) + yy ] & 0x0000FFFF;
};

// ── NO TRIGONOMETRY BELOW THIS LINE, ON PURPOSE ─────────────────────────────
// IEEE-754 pins + - * / and Math.floor/ceil/abs/min/max to the bit, on every
// engine. It does NOT pin sin, cos, atan2, pow or sqrt: ECMA-262 leaves those
// implementation-approximated, so two machines (or two V8 versions) can differ
// in the last ulp - and one ulp either side of a "is this cell inside the blob"
// compare is a DIFFERENT MAP from the same seed. Nothing catches that locally,
// because locally it always agrees with itself.
//
// So every shape in here is built from integer offsets, squared-distance
// compares (never a sqrt), and the Perlin field - whose fade/lerp/grad are pure
// multiply-add and therefore exact too. 16 headings as whole-number vectors,
// lengths 4 to 4.47, stepped at a quarter each so a walk advances about one
// cell at a time. This is what makes the world reproducible off the seed on a
// machine that is not this one, which is the whole point of seeding it.
STIMMINGS_MAP_GEN.WALK_DIRS = [
    [ 4, 0],[ 4, 2],[ 3, 3],[ 2, 4],[ 0, 4],[-2, 4],[-3, 3],[-4, 2],
    [-4, 0],[-4,-2],[-3,-3],[-2,-4],[ 0,-4],[ 2,-4],[ 3,-3],[ 4,-2]
];

// A cheap, deterministic per-cell dice.
//
// randFrom() below is ONE step of an LCG and its low bits are weak, which shows
// up as faint diagonal banding the moment you use it to texture a whole patch
// instead of a single lookup. This mixes the coordinates properly first. Every
// operation is exact 32-bit integer arithmetic - Math.imul and >>> 0 are both
// specified to the bit in ECMAScript - so the same salt and cell give the same
// number on every machine, which is the only property that actually matters
// here: the wilds have to redraw identically from the seed.
STIMMINGS_MAP_GEN.cellDice = function( salt, xx, yy ){
    let h = Math.imul( (salt | 0) ^ (xx | 0), 0x27d4eb2d ) >>> 0;
    h = ( h ^ (h >>> 15) ) >>> 0;
    h = Math.imul( h ^ (yy | 0), 0x165667b1 ) >>> 0;
    h = ( h ^ (h >>> 13) ) >>> 0;
    h = Math.imul( h, 0x9e3779b1 ) >>> 0;
    return ( (h ^ (h >>> 16)) >>> 0 ) / 4294967296;
};

STIMMINGS_MAP_GEN.randFrom = function( seed ){
    let a = 1664525;
    var c = 1013904223;
    c = a * seed + c;
    return (c & 0x00FFFFFF)  / 0x01000000;
}

// A private stream off the seeded chain that does NOT advance it - the same
// SHA1 walk, started from the chain's current link plus `label`, so it is as
// reproducible from the seed as the chain itself, and every rand.random() after
// it returns exactly what it would have without it. For a layer that should be
// free to change without moving anything drawn after it. Like the chain, its
// random() can return exactly 1.
STIMMINGS_MAP_GEN.forkChain = function( rand, label ){
    let link = rand.sha1( rand.state.lastseed + '|' + label );
    return {
        random: function(){
            link = rand.sha1( link );
            return rand.hashToFloat( link );
        }
    };
};


 

