// Every palette goes through here once, out loud, before a cell is written.
//
// STAD is ONE namespace holding entity IDs, sprite packages and SFX keys, and
// ents_consts.js pre-declares every entity name as 0 whether or not its NU_ENT
// ever ran. So a registration someone commented out leaves the name resolving
// to 0 - ent_nothing - and a palette entry like that paints HOLES in the world
// while looking completely correct in the source. That is not hypothetical:
// STAD.ent_hardstone reads 0 today because its NU_WALL_ENT is commented out in
// all_ents.js, and a seam rind made of it quietly erased itself.
//
// An id is only real if it is above 0 (0 is Nothing) AND there is actually a
// row at that index. Bad entries are dropped and named, so the console says
// which palette and which slot instead of leaving you to find it on the map.
STIMMINGS_MAP_GEN.liveEnts = function( label, list ){
    let out = [];
    for(let n = 0;n < list.length;n++){
        let id = list[n];
        if( typeof id === 'number' && id > 0 && FullEntEntries[ id ] !== undefined ){
            out.push( id );
        }
        else{
            console.log('MAPGEN: palette "' + label + '" slot ' + n + ' is not a live entity (got ' + id
                + ') - dropped. Is its NU_ENT commented out in all_ents.js, or the name misspelled?');
        }
    }
    if( out.length < 1 ){
        console.log('MAPGEN: palette "' + label + '" is EMPTY once checked - the pass that uses it is skipped.');
    }
    return out;
};

