// QUADRANT location tracker
STIMMINGS_MAP_GEN.directTheQuadrantType = function( entType, initialState, glength, attlength, xx, yy, chunkdindf, teamm ){

    let valind = STIMMINGS_MAP_GEN.randFrom( chunkdindf );
 
    let qt = STIMMINGS_MAP_GEN.quadrantTypes[ Math.floor( chunkdindf % STIMMINGS_MAP_GEN.quadrantTypes.length ) ]

    if( STIMMINGS_MAP_GEN.randFrom( valind*12325 + xx*819 + yy*13 ) < 0.09 ){
        entType = qt.speck;  
    }
    else if( xx%27 === 13 && yy%27 === 13 ){
        entType = qt.middle; 
    }
    else{
        entType = qt.main;  
    } 

    let teamToUse = qt.TEAM +0;
    if( (FullEntEntries[entType][4] & PHYS.PHYSICS_ALLEGIANCED) < 1 ){teamToUse=0;}    // TODO is ther e amore graceful way to deal w this?! No Owenrhesip  - dont explictiyl dissalow it - dont add ruels for no reason 
    initialState[ (0*attlength) + (xx*glength) + yy ] = EZWG.createPackedU32_16( EZWG.createPackedU16_8(EZWG.createPackedU8(0, 4), teamToUse), entType );  // CPU Hook, TEAM #,     TYPE of entity wall
    initialState[ (1*attlength) + (xx*glength) + yy ] =   
                            EZWG.createPackedU32( 0, 0, 121, EZWG.createPackedU8( 0, 4 ) );//CTRL_detail, CTRL_tag, random prio, next movement direction
                            // (1-4) nextSpawn,   0-7 nextMove (4=stationary)
    initialState[ (2*attlength) + (xx*glength) + yy ] = EZWG.createPackedU32_16( 0, 0 );
    initialState[ (3*attlength) + (xx*glength) + yy ] = EZWG.createPackedU32_16( 0, 0 );

    initialState[ (4*attlength) + (xx*glength) + yy ] =     // scents
        EZWG.createPackedU32( 0, 0, 0, 0);
    initialState[ (5*attlength) + (xx*glength) + yy ] =     // scents
        EZWG.createPackedU32( 0, 0, 0, 0);
    initialState[ (6*attlength) + (xx*glength) + yy ] =     // scents
        EZWG.createPackedU32( 0, 0, 0, 0);
    initialState[ (7*attlength) + (xx*glength) + yy ] =     // scents
        EZWG.createPackedU32( 0, 0, 0, 0);
        
    initialState[ (8*attlength) + (xx*glength) + yy ] =     // util scents
        EZWG.createPackedU32( 0, 0, 0, 0);
    initialState[ (9*attlength) + (xx*glength) + yy ] =     // util scents
        EZWG.createPackedU32( 0, 0, 0, 0);
    initialState[ (10*attlength) + (xx*glength) + yy ] =     // Function values
        EZWG.createPackedU32_4( 0,0,0,0,   0,0,0,0 );
    initialState[ (11*attlength) + (xx*glength) + yy ] =     // Function values
        EZWG.createPackedU32_4( 0,0,0,0,   0,0,0,0 );
    initialState[ (12*attlength) + (xx*glength) + yy ] =     // Light values
        EZWG.createPackedU32( 0, 0, 0, 0);

}

STIMMINGS_MAP_GEN.blankNuffin = function( rand, initialState, glength, attlength, NumOfRandomStructs, NumOfFoilageSpots ){ 
    let per = new PerlinNoise( rand ); 

    let valum = -0.1;

    for(let xx = 0;xx < glength;xx++){
        for(let yy = 0;yy < glength;yy++){

            STIMMINGS_MAP_GEN.createEntity( 0, initialState, glength, attlength, xx, yy, 0 );
        }
    }

    // The edge is a property of the world, not of a map style - the blank map
    // wraps exactly like the others do.
    STIMMINGS_MAP_GEN.PLACE_BORDER_WALL( initialState, glength, attlength );

}

STIMMINGS_MAP_GEN.perlin_W_TightWinding = function( rand, initialState, glength, attlength, NumOfRandomStructs, NumOfFoilageSpots ){ 
    let per = new PerlinNoise( rand ); 

    let valum = -0.1;

    for(let xx = 0;xx < glength;xx++){
        for(let yy = 0;yy < glength;yy++){
            
            let noise_here = per.noise( xx / 13, yy / 13 );

            // Basically combined make the id of the quadrant
            let chx = Math.floor(xx/27);
            let chy = Math.floor(yy/27);

            if( yy === 23 &&  xx === glength-24 && false ){
                //STIMMINGS_MAP_GEN.createTC_5( initialState, glength, attlength, xx, yy, 1 );
            }
            // On a special grid area 
            else if( chx%2===0 && chy%2===1 ){
                let TEAM_ID_OVERRIDE = 0;
                STIMMINGS_MAP_GEN.directTheQuadrantType( 0, initialState, glength, attlength, xx, yy, (Math.floor(chx/2)+(27*chy)), TEAM_ID_OVERRIDE );
                //STIMMINGS_MAP_GEN.createOrb( initialState, glength, attlength, xx, yy, TEAM_ID, (chx + chy*glength) );
                //STIMMINGS_MAP_GEN.createEntity( 8, initialState, glength, attlength, xx, yy, 1 );
            }
            else{
                if( noise_here > valum ){ 
                    STIMMINGS_MAP_GEN.createEntity( 0, initialState, glength, attlength, xx, yy, 0 );
                }
                // Just the normal wall (no team)
                else{
                    STIMMINGS_MAP_GEN.createEntity( STAD.ent_oilr_wall, initialState, glength, attlength, xx, yy, 0 );
                }
            }
             

        }
    }


    STIMMINGS_MAP_GEN.UNIVERSAL_PLACE_STRUCTURES(rand, initialState, glength, attlength, NumOfRandomStructs, NumOfFoilageSpots );



};

// ── THREE MORE ISLAND VARIANTS ──────────────────────────────────────────────
// Same trick as perlin_W_TightWinding (a noise field thresholded into open
// ground vs ent_oilr_wall) but none of them carry its quadrant-grid overlay -
// these are pure silhouettes, and SCATTER_THE_WILDS is what fills them in.
// Only the noise scale/threshold differ, so each reads as a different kind of
// coastline rather than a different generator.

// A few broad continents - land dominates, water is the exception.
STIMMINGS_MAP_GEN.perlin_W_LooseIslands = function( rand, initialState, glength, attlength, NumOfRandomStructs, NumOfFoilageSpots ){
    let per = new PerlinNoise( rand );
    let valum = -0.35;

    for(let xx = 0;xx < glength;xx++){
        for(let yy = 0;yy < glength;yy++){
            let noise_here = per.noise( xx / 34, yy / 34 );
            if( noise_here > valum ){
                STIMMINGS_MAP_GEN.createEntity( 0, initialState, glength, attlength, xx, yy, 0 );
            }
            else{
                STIMMINGS_MAP_GEN.createEntity( STAD.ent_oilr_wall, initialState, glength, attlength, xx, yy, 0 );
            }
        }
    }

    STIMMINGS_MAP_GEN.UNIVERSAL_PLACE_STRUCTURES(rand, initialState, glength, attlength, NumOfRandomStructs, NumOfFoilageSpots );
};

// Lots of small islands - high frequency, high threshold, mostly water/wall.
STIMMINGS_MAP_GEN.perlin_W_Archipelago = function( rand, initialState, glength, attlength, NumOfRandomStructs, NumOfFoilageSpots ){
    let per = new PerlinNoise( rand );
    let valum = 0.28;

    for(let xx = 0;xx < glength;xx++){
        for(let yy = 0;yy < glength;yy++){
            let noise_here = per.noise( xx / 8, yy / 8 );
            if( noise_here > valum ){
                STIMMINGS_MAP_GEN.createEntity( 0, initialState, glength, attlength, xx, yy, 0 );
            }
            else{
                STIMMINGS_MAP_GEN.createEntity( STAD.ent_oilr_wall, initialState, glength, attlength, xx, yy, 0 );
            }
        }
    }

    STIMMINGS_MAP_GEN.UNIVERSAL_PLACE_STRUCTURES(rand, initialState, glength, attlength, NumOfRandomStructs, NumOfFoilageSpots );
};

// Jagged coastlines - a coarse octave for the landmass, a fine one riding on
// top of it to fray the edge instead of leaving it a smooth contour.
STIMMINGS_MAP_GEN.perlin_W_Fractured = function( rand, initialState, glength, attlength, NumOfRandomStructs, NumOfFoilageSpots ){
    let per = new PerlinNoise( rand );
    let valum = -0.05;

    for(let xx = 0;xx < glength;xx++){
        for(let yy = 0;yy < glength;yy++){
            let noise_here = per.noise( xx / 21, yy / 21 ) + 0.45 * per.noise( xx / 6, yy / 6 );
            if( noise_here > valum ){
                STIMMINGS_MAP_GEN.createEntity( 0, initialState, glength, attlength, xx, yy, 0 );
            }
            else{
                STIMMINGS_MAP_GEN.createEntity( STAD.ent_oilr_wall, initialState, glength, attlength, xx, yy, 0 );
            }
        }
    }

    STIMMINGS_MAP_GEN.UNIVERSAL_PLACE_STRUCTURES(rand, initialState, glength, attlength, NumOfRandomStructs, NumOfFoilageSpots );
};

// ── THE PERLIN POOL ──────────────────────────────────────────────────────
// generator 0 ("Perlin Noise" in the dropdown) no longer means exactly
// perlin_W_TightWinding - it means "draw one variant from this pool", picked
// off the seeded chain so it stays deterministic per seed. Add a variant by
// writing the function above and appending it here; nothing else has to know
// the pool got bigger.
// { label, fn } rather than bare functions - `obj.prop = function(){}` never
// gets its name inferred (NamedEvaluation only applies to a simple identifier
// on the left), so pick.fn.name would always come back empty here.
STIMMINGS_MAP_GEN.PERLIN_ISLAND_POOL = [
    { label: 'TightWinding', fn: STIMMINGS_MAP_GEN.perlin_W_TightWinding },
    { label: 'LooseIslands', fn: STIMMINGS_MAP_GEN.perlin_W_LooseIslands },
    { label: 'Archipelago',  fn: STIMMINGS_MAP_GEN.perlin_W_Archipelago },
    { label: 'Fractured',    fn: STIMMINGS_MAP_GEN.perlin_W_Fractured }
];

STIMMINGS_MAP_GEN.perlin_W_Pooled = function( rand, initialState, glength, attlength, NumOfRandomStructs, NumOfFoilageSpots ){
    let pool = STIMMINGS_MAP_GEN.PERLIN_ISLAND_POOL;
    let pick = pool[ Math.floor( pool.length * rand.random() ) ];
    console.log('MAPGEN: perlin pool picked "' + pick.label + '"');
    pick.fn( rand, initialState, glength, attlength, NumOfRandomStructs, NumOfFoilageSpots );
};


// ── REAL ESTATE ─────────────────────────────────────────────────────────────
// The map as a surveyed grid of plots rather than a noise field. Two layers:
//
//   1  PLOTS   the board is cut into REAL_ESTATE_SIZE squares (16x16, so 64x64
//              = 4096 of them on the 1024 grid). Each is left bare with chance
//              REAL_ESTATE_EMPTY_ODDS (55%) - the breathing space - and
//              otherwise gets one tile type drawn from REAL_ESTATE_TILES.
//   2  SUPERS  one per SUPER_ESTATE_PER_PLOTS plots (512 on the 1024 grid),
//              dropped over the top with their middle on ANY cell, so they
//              straddle plot lines and each other. Each is a square, octagon or
//              septagon that fits a SUPER_ESTATE_SIZE box (32x32), and draws from
//              its own pool, SUPER_ESTATE_TILES. Every cell inside the outline is
//              rewritten, bare ones included, so the silhouette reads cleanly
//              against whatever it landed on.
//
// Then the same UNIVERSAL_PLACE_STRUCTURES as every other generator - random
// blueprints, the four team spawns, chests, foliage, the world edge - minus
// the wilds, which would cut clearings through the grid and grow groves back
// into the bare plots. REAL_ESTATE_WITH_WILDS puts them back.
//
// Generator 2 in the dropdown. APPENDED rather than given slot 0: a save
// records the generator's number and a replay regenerates from it, so
// renumbering would quietly hand every old save the wrong world.
STIMMINGS_MAP_GEN.REAL_ESTATE_SIZE       = 16;     // keep it even - a plot is 2h cells across
STIMMINGS_MAP_GEN.REAL_ESTATE_EMPTY_ODDS = 0.55;
STIMMINGS_MAP_GEN.SUPER_ESTATE_SIZE      = 32;     // even, same reason
STIMMINGS_MAP_GEN.SUPER_ESTATE_PER_PLOTS = 16;
STIMMINGS_MAP_GEN.REAL_ESTATE_WITH_WILDS = false;

// A TILE TYPE is a small recipe rather than one entity, so a single pool can
